// GroupByAgg is the vec aggregation/grouping node. It fuses GroupBy and a
// single Aggregation into one BatchAggregation operator (see G7d
// planner), and also covers the two single-sided shapes:
//
//   - GroupBy + Agg → BatchAggregation: key columns + one agg result
//     column (schema-rewriting; timestamp dropped, per G7 decision D2).
//   - Agg without GroupBy → scalar reduce: BatchAggregation with no key
//     columns, a single output row (first-seen tags + agg result).
//   - GroupBy without Agg → raw GroupBy: a first-seen-row-per-group
//     BatchGroupBy, schema-preserving.
//
// The concrete operator (and therefore the output schema) is chosen by
// vmeasure.BuildOperators from which of GroupBy/Agg is set. Mode selects
// AggModeAll (single-node final reduce) vs AggModeMap (G9f.2 distributed
// Map phase emitting typed-column partials). Mode is irrelevant for raw
// GroupBy (BatchGroupBy doesn't carry partial state).
type GroupByAgg struct {
	Child       VecPlan
	GroupBy     *model.MeasureGroupBy
	Agg         *model.MeasureAgg
	outputCache *vectorized.BatchSchema
	Mode        vmeasure.AggMode
}

// NewGroupByAgg constructs a GroupByAgg node wrapping child. At least one
// of groupBy/agg must be set (BuildOperators routes on which); child must
// not be nil. mode selects AggModeAll for the single-node path or
// AggModeMap for the distributed Map phase (G9f.2); AggModeReduce is
// rejected here (the reduce plan is built liaison-side in G9f.3).
func NewGroupByAgg(child VecPlan, groupBy *model.MeasureGroupBy, agg *model.MeasureAgg, mode vmeasure.AggMode) (*GroupByAgg, error) {
	if groupBy == nil && agg == nil {
		return nil, fmt.Errorf("plan.GroupByAgg: GroupBy and Agg must not both be nil")
	}
	if child == nil {
		return nil, fmt.Errorf("plan.GroupByAgg: Child must not be nil")
	}
	if mode == vmeasure.AggModeReduce {
		return nil, fmt.Errorf("plan.GroupByAgg: AggModeReduce is built by the liaison reduce plan (G9f.3), not here")
	}
	return &GroupByAgg{Child: child, GroupBy: groupBy, Agg: agg, Mode: mode}, nil
}

// Schema returns the aggregation output schema. The schema is computed
// lazily on first call by running BuildOperators (or, for a time-bucketed
// GroupBy, BuildTimeBucketOperator with a nil upstream — see its doc)
// against the child schema; subsequent calls return the cached value.
func (g *GroupByAgg) Schema() *vectorized.BatchSchema {
	if g.outputCache != nil {
		return g.outputCache
	}
	if g.Child == nil {
		return nil
	}
	inputSchema := g.Child.Schema()
	if inputSchema == nil {
		return nil
	}
	// Synthesize a transient MeasureQueryOptions to drive the planner.
	opts := model.MeasureQueryOptions{GroupBy: g.GroupBy, Agg: g.Agg}
	// A throwaway tracker; we only need the resulting operator's
	// OutputSchema, not its bookkeeping.
	tracker := vectorized.NewMemoryTracker(1 << 30)
	if g.GroupBy != nil && g.GroupBy.TimeBucket != nil {
		bucket, err := vmeasure.BuildTimeBucketOperator(nil, opts, inputSchema, tracker, 1024, g.Mode)
		if err != nil {
			return nil
		}
		g.outputCache = bucket.OutputSchema()
		return g.outputCache
	}
	ops, err := vmeasure.BuildOperators(opts, inputSchema, tracker, 1024, g.Mode)
	if err != nil || len(ops) != 1 {
		return nil
	}
	g.outputCache = ops[0].OutputSchema()
	return g.outputCache
}

// Children returns the single child.
func (g *GroupByAgg) Children() []VecPlan { return []VecPlan{g.Child} }

// Build recurses into child, then attaches the aggregation operator. A
// time-bucketed GroupBy wires BatchTimeBucket in via
// PipelineBuilder.Transform, since it is a PullOperator that pulls from
// upstream directly rather than a BreakerOperator driven by Break's
// Consume/Finalize contract (see BatchTimeBucket's doc for why that
// distinction is what makes its memory bound real). Every other shape
// attaches its BatchAggregation/BatchGroupBy via Break, as before. The
// pipeline-shared MemoryTracker from bc threads through either way.
func (g *GroupByAgg) Build(ctx context.Context, bc *BuildContext) error {
	if buildErr := g.Child.Build(ctx, bc); buildErr != nil {
		return buildErr
	}
	inputSchema := g.Child.Schema()
	opts := model.MeasureQueryOptions{GroupBy: g.GroupBy, Agg: g.Agg}

	if g.GroupBy != nil && g.GroupBy.TimeBucket != nil {
		var bucket *vmeasure.BatchTimeBucket
		var buildErr error
		bc.Builder.Transform(func(upstream vectorized.PullOperator) vectorized.PullOperator {
			bucket, buildErr = vmeasure.BuildTimeBucketOperator(upstream, opts, inputSchema, bc.Tracker, bc.Config.BatchSize, g.Mode)
			if buildErr != nil {
				return upstream
			}
			return bucket
		})
		if buildErr != nil {
			return fmt.Errorf("plan.GroupByAgg.Build: %w", buildErr)
		}
		g.outputCache = bucket.OutputSchema()
		return nil
	}

	ops, opsErr := vmeasure.BuildOperators(opts, inputSchema, bc.Tracker, bc.Config.BatchSize, g.Mode)
	if opsErr != nil {
		return fmt.Errorf("plan.GroupByAgg.Build: %w", opsErr)
	}
	if len(ops) != 1 {
		return fmt.Errorf("plan.GroupByAgg.Build: expected 1 operator, got %d", len(ops))
	}
	bc.Builder.Break(ops[0])
	// Cache for subsequent Schema() queries — saves re-running the planner.
	g.outputCache = ops[0].OutputSchema()
	return nil
}

// String returns a single-line debug description.
func (g *GroupByAgg) String() string {
	tagNames := ""
	if g.GroupBy != nil {
		tagNames = strings.Join(g.GroupBy.TagNames, ",")
	}
	if g.Agg == nil {
		return fmt.Sprintf("GroupByAgg(keys=%s, raw)", tagNames)
	}
	target := g.Agg.FieldName
	if g.Agg.TagName != "" {
		target = g.Agg.TagName
	}
	return fmt.Sprintf("GroupByAgg(keys=%s, fn=%v, target=%s)", tagNames, g.Agg.Func, target)
}

	tbProto := groupByProto.GetTimeBucket()
	if len(families) == 0 && tbProto == nil {
		return nil, fmt.Errorf("plan.Analyze: GroupBy must set tag_projection, time_bucket, or both")
	}

	gb := &model.MeasureGroupBy{}
	if len(families) > 0 {
		if len(families) > 1 {
			return nil, fmt.Errorf("plan.Analyze: GroupBy.tag_projection v1 supports a single tag family, got %d", len(families))
		}
		family := families[0]
		if len(family.GetTags()) == 0 {
			return nil, fmt.Errorf("plan.Analyze: GroupBy.tag_projection family %q has no tags", family.GetName())
		}
		gb.TagFamily = family.GetName()
		gb.TagNames = append([]string(nil), family.GetTags()...)
		if validateErr := validateGroupByTags(measureSchema, gb); validateErr != nil {
			return nil, validateErr
		}
	}

	if tbProto != nil {
		// A time-bucketed GroupBy without an Agg has no execution support:
		// BatchTimeBucket's raw (no-AggSpec) shape reuses BatchAggregation's
		// output layout, which — unlike BatchGroupByFirst's full schema
		// passthrough — carries only tags and the bucket timestamp, silently
		// dropping every projected field (and, on the distributed path, the
		// series-id/version columns raw row merging requires). Reject rather
		// than silently lose data; a bucketed raw GroupBy is a possible
		// follow-up, not something this design ships.
		if req.GetAgg() == nil {
			return nil, fmt.Errorf("plan.Analyze: time_bucket requires Agg; a bucketed raw GroupBy (no aggregate) is not supported yet")
		}
		tb, tbErr := resolveTimeBucket(tbProto, measureSchema)
		if tbErr != nil {
			return nil, tbErr
